ctx_raw = subprocess.run(['uip','maestro','flow','registry','get',
    'uipath.agent.resource.context.index.billing-dispute-sop-index.cc45b9b4-dbf6-47b3-40ac-08debc0cec5b',
    '--output','json'], capture_output=True, text=True)
ctx_def = json.loads(ctx_raw.stdout)['Data']['Node']

api_raw = subprocess.run(['uip','maestro','flow','registry','get',
    'uipath.core.api-workflow.07d45a91-9413-4dad-82ff-28306c2d85ea',
    '--output','json'], capture_output=True, text=True)
api_def = json.loads(api_raw.stdout)['Data']['Node']

# ============================================================
# NEW USER-OWNED NODES
# ============================================================

# 1. IxP extraction node
