    },
    "outputs": {
        "output": {
            "type": "object",
            "description": "Extraction result",
            "source": "=result.response",
            "var": "output"
        },
        "error": {
            "type": "object",
            "description": "Error information if the node fails",
            "source": "=Error",
            "var": "error"
        }
    }
}

# IxP bindings
ixp_bindings = [
    {
        "id": "bIxpName",
        "name": "name",
        "type": "string",
        "resource": "ixpDeployment",
        "resourceKey": "99f5bbfa-5f29-8033-8662-25001b6bb18e",
        "propertyAttribute": "name",
        "default": "invoices-billing"
    },
    {
        "id": "bIxpFolderPath",
        "name": "folderPath",
        "type": "string",
        "resource": "ixpDeployment",
        "resourceKey": "99f5bbfa-5f29-8033-8662-25001b6bb18e",
        "propertyAttribute": "folderPath",
        "default": "Shared/uipath-maestro-flow/BillingDispute"
    }
]

# 2. Normalize Data script
normalize_script = """function run({ ixpExtract1, start }) {
  const fields = (ixpExtract1?.output?.ExtractionResult?.ResultsDocument?.Fields || []);
  const getField = (name) => {
    const f = fields.find(x => x.FieldName === name);
    return f ? (f.Values?.[0]?.Value ?? null) : null;
  };
  const rawInvoiceNumber = getField('InvoiceNumber') || '';
  const normalizedInvoiceNumber = rawInvoiceNumber.startsWith('MCS-') ? rawInvoiceNumber : ('MCS-' + rawInvoiceNumber);
  return {
    normalizedInvoiceNumber,
    vendorName: getField('VendorName'),
    invoiceDate: getField('InvoiceDate'),
    totalAmount: parseFloat(getField('TotalAmount') || '0'),
    lineItems: fields.filter(x => x.FieldName === 'LineItem').map(x => ({
      description: x.Values?.[0]?.Value,
      amount: parseFloat(x.Values?.[1]?.Value || '0')
    }))
  };
}"""

normalize_node = {
    "id": "normalizeData1",
    "type": "core.action.script",
    "typeVersion": script_def['version'],
    "display": {"label": "Normalize Data"},
    "inputs": {
        "script": normalize_script
    }
}

# 3. CRM and ERP lookups already in flow (crmLookup1, erpLookup1)

# 4. Merge node
merge_node = {
    "id": "merge1",
    "type": "core.logic.merge",
    "typeVersion": merge_def['version'],
    "display": {"label": "Merge"},
    "inputs": {}
}

# 5. Discrepancy Detection script
discrepancy_script = """function run({ normalizeData1, crmLookup1, erpLookup1, start }) {
  const disputedLineItems = start?.output?.webhookPayload?.dispute?.disputedLineItems || [];
  const erpRecords = erpLookup1?.output?.value || [];
  const discrepancies = [];
  let totalOvercharge = 0;
  let totalUndercharge = 0;
  for (const disputed of disputedLineItems) {
    const erp = erpRecords.find(r => r.lineItemId === disputed.lineItemId || r.description === disputed.description);
    if (erp) {
      const billedAmount = parseFloat(disputed.billedAmount || 0);
      const contractAmount = parseFloat(erp.contractAmount || 0);
      const diff = billedAmount - contractAmount;
      if (Math.abs(diff) > 0.01) {
        discrepancies.push({ lineItemId: disputed.lineItemId, description: disputed.description, billedAmount, contractAmount, diff });
        if (diff > 0) totalOvercharge += diff; else totalUndercharge += Math.abs(diff);
      }
    }
  }
  const creditAmount = totalOvercharge;
  const hasDiscrepancies = discrepancies.length > 0;
  return { discrepancies, totalOvercharge, totalUndercharge, creditAmount, hasDiscrepancies };
}"""

