            "rationale": {"source": "=js:$vars.disputeAnalyst1.output.rationale"},
            "resolutionEmailBody": {"source": "=js:$vars.resolutionWriter1.output.body"}
        }
    }

# For endManagerReject and endReject, resolutionWriter hasn't run - use empty string
def make_end_node_no_writer(node_id, label):
    return {
        "id": node_id,
        "type": "core.control.end",
        "typeVersion": end_def['version'],
        "display": {"label": label},
        "inputs": {},
        "outputs": {
            "determination": {"source": "=js:$vars.disputeAnalyst1.output.determination"},
            "recommendedAction": {"source": "=js:$vars.disputeAnalyst1.output.recommendedAction"},
            "creditAmount": {"source": "=js:$vars.disputeAnalyst1.output.creditAmount"},
            "rationale": {"source": "=js:$vars.disputeAnalyst1.output.rationale"},
            "resolutionEmailBody": {"source": "=js:''"}
        }
    }

end_resolution = make_end_node("endResolution", "Return Resolution")
end_reject = make_end_node_no_writer("endReject", "Return Rejection")
end_manager_reject = make_end_node_no_writer("endManagerReject", "Return Manager Rejection")

# ============================================================
# ASSEMBLE NODES
# ============================================================
flow['nodes'] = [
    flow['nodes'][0],   # start (manual trigger)
    ixp_node,
    normalize_node,
    flow['nodes'][1],   # crmLookup1
    flow['nodes'][2],   # erpLookup1
    merge_node,
    discrepancy_node,
    dispute_analyst_node,
    billing_sop_context_node,
    switch_node,
    decision_node,
    financial_node,
    resolution_writer_node,
    end_resolution,
    end_reject,
    end_manager_reject,
]

