    # normalizeData1 -> crmLookup1 (parallel branch 1)
    {"id": "edge_normalizeData1_success_crmLookup1_input", "sourceNodeId": "normalizeData1", "sourcePort": "success", "targetNodeId": "crmLookup1", "targetPort": "input"},
    # normalizeData1 -> erpLookup1 (parallel branch 2)
    {"id": "edge_normalizeData1_success_erpLookup1_input", "sourceNodeId": "normalizeData1", "sourcePort": "success", "targetNodeId": "erpLookup1", "targetPort": "input"},
    # crmLookup1 -> merge1
    {"id": "edge_crmLookup1_output_merge1_input", "sourceNodeId": "crmLookup1", "sourcePort": "output", "targetNodeId": "merge1", "targetPort": "input"},
    # erpLookup1 -> merge1
    {"id": "edge_erpLookup1_output_merge1_input", "sourceNodeId": "erpLookup1", "sourcePort": "output", "targetNodeId": "merge1", "targetPort": "input"},
    # merge1 -> discrepancyDetection1
    {"id": "edge_merge1_output_discrepancyDetection1_input", "sourceNodeId": "merge1", "sourcePort": "output", "targetNodeId": "discrepancyDetection1", "targetPort": "input"},
    # discrepancyDetection1 -> disputeAnalyst1
    {"id": "edge_discrepancyDetection1_success_disputeAnalyst1_input", "sourceNodeId": "discrepancyDetection1", "sourcePort": "success", "targetNodeId": "disputeAnalyst1", "targetPort": "input"},
    # disputeAnalyst1 context edge to billingSopContext1
    {"id": "edge_disputeAnalyst1_context_billingSopContext1_input", "sourceNodeId": "disputeAnalyst1", "sourcePort": "context", "targetNodeId": "billingSopContext1", "targetPort": "input"},
    # disputeAnalyst1 -> switchAction1
    {"id": "edge_disputeAnalyst1_success_switchAction1_input", "sourceNodeId": "disputeAnalyst1", "sourcePort": "success", "targetNodeId": "switchAction1", "targetPort": "input"},
    # switchAction1 escalate_to_manager -> endManagerReject
    {"id": "edge_switchAction1_escalate_to_manager_endManagerReject_input", "sourceNodeId": "switchAction1", "sourcePort": "case-escalate_to_manager", "targetNodeId": "endManagerReject", "targetPort": "input"},
    # switchAction1 auto_resolve -> approvalDecision1
    {"id": "edge_switchAction1_auto_resolve_approvalDecision1_input", "sourceNodeId": "switchAction1", "sourcePort": "case-auto_resolve", "targetNodeId": "approvalDecision1", "targetPort": "input"},
    # switchAction1 reject -> endReject
    {"id": "edge_switchAction1_reject_endReject_input", "sourceNodeId": "switchAction1", "sourcePort": "case-reject", "targetNodeId": "endReject", "targetPort": "input"},
    # switchAction1 default -> endReject (fallback)
    {"id": "edge_switchAction1_default_endReject_input", "sourceNodeId": "switchAction1", "sourcePort": "default", "targetNodeId": "endReject", "targetPort": "input"},
    # approvalDecision1 false (Approved) -> financialPosting1
    {"id": "edge_approvalDecision1_false_financialPosting1_input", "sourceNodeId": "approvalDecision1", "sourcePort": "false", "targetNodeId": "financialPosting1", "targetPort": "input"},
    # approvalDecision1 true (Rejected) -> endReject
    {"id": "edge_approvalDecision1_true_endReject_input", "sourceNodeId": "approvalDecision1", "sourcePort": "true", "targetNodeId": "endReject", "targetPort": "input"},
    # financialPosting1 -> resolutionWriter1
    {"id": "edge_financialPosting1_output_resolutionWriter1_input", "sourceNodeId": "financialPosting1", "sourcePort": "output", "targetNodeId": "resolutionWriter1", "targetPort": "input"},
    # resolutionWriter1 -> endResolution
    {"id": "edge_resolutionWriter1_success_endResolution_input", "sourceNodeId": "resolutionWriter1", "sourcePort": "success", "targetNodeId": "endResolution", "targetPort": "input"},
]

