    {"id": "erpLookup1.output", "type": "object", "description": "The return value of the connector.", "binding": {"nodeId": "erpLookup1", "outputId": "output"}},
    {"id": "erpLookup1.error", "type": "object", "description": "Error information if the node fails", "schema": error_schema, "binding": {"nodeId": "erpLookup1", "outputId": "error"}},
    # Discrepancy detection
    {"id": "discrepancyDetection1.output", "type": "any", "description": "The return value of the script", "binding": {"nodeId": "discrepancyDetection1", "outputId": "output"}},
